package com.centralplay.app.ui;
import android.content.Intent;import android.os.Bundle;import android.view.View;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.centralplay.app.R;import com.centralplay.app.data.HistoryStore;import com.centralplay.app.model.MediaEntry;import com.google.android.material.appbar.MaterialToolbar;import com.google.gson.Gson;import java.util.*;
public class HistoryActivity extends AppCompatActivity{private ContentAdapter adapter;private TextView empty;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_history);MaterialToolbar tb=findViewById(R.id.toolbar);tb.setNavigationOnClickListener(v->finish());tb.inflateMenu(R.menu.menu_history);tb.setOnMenuItemClickListener(i->{if(i.getItemId()==R.id.action_clear_history){HistoryStore.clear(this);reload();return true;}return false;});RecyclerView rv=findViewById(R.id.recycler);empty=findViewById(R.id.empty);rv.setLayoutManager(new GridLayoutManager(this,2));adapter=new ContentAdapter(this,new ContentAdapter.Listener(){public void onClick(ContentAdapter.Row row){if(row.media==null)return;Intent i=new Intent(HistoryActivity.this,PlayerActivity.class);i.putExtra("media",new Gson().toJson(row.media));startActivity(i);}public void onLongClick(ContentAdapter.Row row){}});rv.setAdapter(adapter);reload();}private void reload(){List<ContentAdapter.Row> rows=new ArrayList<>();for(MediaEntry m:HistoryStore.get(this))rows.add(ContentAdapter.Row.media(m));adapter.setRows(rows,"");empty.setVisibility(adapter.getItemCount()==0?View.VISIBLE:View.GONE);}}
